package io.github.diodeme.ji.agent;

import io.github.diodeme.ji.ai.Message;
import io.github.diodeme.ji.ai.Usage;
import io.github.diodeme.ji.error.JiError;
import java.time.Instant;
import java.util.Map;

/** Public immutable event stream from one Session. */
public sealed interface AgentEvent permits AgentEvent.RunStarted, AgentEvent.MessageAdded,
        AgentEvent.TextStreamed, AgentEvent.ToolChanged, AgentEvent.PermissionChanged,
        AgentEvent.UsageChanged, AgentEvent.RunFinished, AgentEvent.RunFailed {
    String sessionId();
    String runId();
    Instant occurredAt();

    record RunStarted(String sessionId, String runId, Instant occurredAt) implements AgentEvent {}
    record MessageAdded(String sessionId, String runId, Message message, Instant occurredAt) implements AgentEvent {}
    record TextStreamed(String sessionId, String runId, String messageId, String accumulatedText, long streamSeq,
                        Instant occurredAt) implements AgentEvent {}
    record ToolChanged(String sessionId, String runId, String toolCallId, String toolName, ToolStatus status,
                       Map<String, Object> arguments, String result, Instant occurredAt) implements AgentEvent {
        public ToolChanged { arguments = Map.copyOf(arguments); }
    }
    record PermissionChanged(String sessionId, String runId, PermissionDecider.Request request,
                             PermissionStatus status, Instant occurredAt) implements AgentEvent {}
    record UsageChanged(String sessionId, String runId, Usage usage, Instant occurredAt) implements AgentEvent {}
    record RunFinished(String sessionId, String runId, Outcome outcome, Instant occurredAt) implements AgentEvent {}
    record RunFailed(String sessionId, String runId, JiError error, Instant occurredAt) implements AgentEvent {}

    enum ToolStatus { PENDING, WAITING_PERMISSION, RUNNING, COMPLETED, FAILED, DENIED }
    enum PermissionStatus { PENDING, ALLOWED, DENIED }
    enum Outcome { COMPLETED, ABORTED, DECLINED }
}
